target.css:
:root {
  --paper: #fffdf7;
  --ink: #24343a;
  --muted: #718083;
  --line: #d8ddd5;
  --accent: #d85f43;
  --accent-soft: #fae5dc;
  --deep: #315d62;
}

* {
  box-sizing: border-box;
}

.film-card {
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 17px 18px 15px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0 0 5px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.1px;
}

h1,
h2,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 0;
  font-size: 21px;
  line-height: 1.1;
}

.status {
  padding: 5px 8px;
  color: var(--accent);
  background: var(--accent-soft);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.film-details {
  display: grid;
  grid-template-columns: 72px 1fr;
  gap: 15px;
  align-items: center;
  padding: 15px 18px;
}

.date-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 82px;
  color: var(--deep);
  background: var(--accent-soft);
  border-radius: 12px;
}

.date-block span,
.date-block small {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.9px;
}

.date-block strong {
  font-size: 30px;
  line-height: 1;
}

.roll-info h2 {
  margin-bottom: 4px;
  font-size: 15px;
  line-height: 1.25;
}

.roll-info p {
  margin-bottom: 10px;
  color: var(--muted);
  font-size: 13px;
}

.spec-list {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  padding: 0;
  margin: 0;
  list-style: none;
}

.spec-list li {
  padding: 3px 7px;
  border: 1px solid var(--line);
  border-radius: 5px;
  color: var(--deep);
  font-size: 11px;
  font-weight: 700;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 18px;
  background: var(--deep);
}

.card-footer p {
  margin-bottom: 0;
  color: var(--paper);
  font-size: 13px;
}

.card-footer button {
  padding: 7px 10px;
  color: var(--deep);
  background: var(--paper);
  border: 0;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 800;
}

.card-footer button span {
  margin-left: 5px;
  color: var(--accent);
  font-size: 15px;
}

